// 面积 = 底(r-l) * 较矮高度。宽度变小时，只有更高的边才可能刷新答案，
// 所以每次丢掉较矮的一侧。两边一样高时丢掉哪边都可以，这里统一 left++。
// 换题：有序两数之和改成 sum<target 则 l++，sum>target 则 r--；
// 回文改成跳过无效字符后比较 s[l] 与 s[r]，不等则失败。
static int maxArea(int[] height) {
    int l = 0, r = height.length - 1, best = 0;
    while (l < r) {
        int h = Math.min(height[l], height[r]);
        best = Math.max(best, h * (r - l));
        if (height[l] <= height[r]) l++;
        else r--;
    }
    return best;
}

// 排序后枚举 i，在 (i, n) 上夹逼。每步：和偏小则 l++，偏大则 r--，等于 0 则收录。
// 去重：外层跳过相同的 nums[i]；命中后内层跳过刚刚用过的左右重复值。
// 换题：目标和不是 0 时，把下面三处与 0 的比较改成 target。
// 若要统计下标方案而不是按值去重的三元组，不要 skip 相同值，命中时按重复次数计入。
static List<List<Integer>> threeSum(int[] nums) {
    Arrays.sort(nums);
    List<List<Integer>> ans = new ArrayList<>();
    int n = nums.length;
    for (int i = 0; i < n - 2; i++) {
        if (i > 0 && nums[i] == nums[i - 1]) continue;
        if (nums[i] + nums[i + 1] + nums[i + 2] > 0) break;
        if (nums[i] + nums[n - 2] + nums[n - 1] < 0) continue;
        int l = i + 1, r = n - 1;
        while (l < r) {
            int sum = nums[i] + nums[l] + nums[r];
            if (sum == 0) {
                ans.add(Arrays.asList(nums[i], nums[l], nums[r]));
                l++;
                r--;
                while (l < r && nums[l] == nums[l - 1]) l++;
                while (l < r && nums[r] == nums[r + 1]) r--;
            } else if (sum < 0) {
                l++;
            } else {
                r--;
            }
        }
    }
    return ans;
}

// slow 左侧是已按原相对顺序放好的非零元素。因为 slow<=fast，写入不会盖住还没读的 nums[fast]。
// 扫完后 slow 之后全部填 0。
// 换题：移除等于 val 的元素时，把 != 0 改成 != val，返回 slow 作为新长度，不要补 0。
// 颜色分类或奇偶交换分区不是这种覆盖写法，用边界指针交换，见变体。
static void moveZeroes(int[] nums) {
    int slow = 0;
    for (int fast = 0; fast < nums.length; fast++) {
        if (nums[fast] != 0) nums[slow++] = nums[fast];
    }
    while (slow < nums.length) nums[slow++] = 0;
}

