import java.util.*;

class Solution {
    public int maxArea(int[] height) {
        int left = 0;
        int right = height.length - 1;
        int answer = 0;

        while (left < right) {
            // 宽度乘较短边，才是当前两条线的盛水量
            int width = right - left;
            int level = Math.min(height[left], height[right]);
            answer = Math.max(answer, width * level);

            // 短板限制面积，只移动较矮一侧才可能变高
            if (height[left] < height[right]) {
                left++;
            } else {
                right--;
            }
        }
        return answer;
    }
}

import java.util.*; // 模板导入，本题只使用下标与局部变量

class Solution {
    public int trap(int[] height) {
        int left = 0, right = height.length - 1;
        int leftMax = 0, rightMax = 0;
        int water = 0;

        while (left < right) {
            // 已处理两侧最高值 <= 当前两端较高值；结算较矮端时，对侧足以挡住本侧更新后的最高值。
            if (height[left] < height[right]) {
                leftMax = Math.max(leftMax, height[left]);
                water += leftMax - height[left];
                left++;
            } else {
                // 右端不高于左端，用 rightMax 结算后只把 right 向左收一格。
                rightMax = Math.max(rightMax, height[right]);
                water += rightMax - height[right];
                right--;
            }
        }
        return water;
    }
}

class Solution {
    public boolean isPalindrome(String s) {
        int left = 0;
        int right = s.length() - 1;

        while (left < right) {
            // 只比较字母和数字，标点与空格不参与回文判定。
            while (left < right && !Character.isLetterOrDigit(s.charAt(left))) {
                left++;
            }
            while (left < right && !Character.isLetterOrDigit(s.charAt(right))) {
                right--;
            }

            char a = Character.toLowerCase(s.charAt(left));
            char b = Character.toLowerCase(s.charAt(right));
            if (a != b) return false; // 忽略大小写后仍不同，则不是回文。

            left++;
            right--; // 这一对已匹配，两侧都要向中间移动。
        }
        return true;
    }
}

import java.util.*;

class Solution {
    public int[] sortedSquares(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];

        int left = 0;
        int right = n - 1;
        int write = n - 1;

        // 有序数组里，未处理区间的最大平方只可能在左右端点。
        while (left <= right) {
            int leftSquare = nums[left] * nums[left];
            int rightSquare = nums[right] * nums[right];

            if (leftSquare > rightSquare) {
                answer[write--] = leftSquare;
                left++;
            } else {
                // 右端不小于左端（含相等）时先放右端，保证从大到小写入。
                answer[write--] = rightSquare;
                right--;
            }
        }

        return answer;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums); // 有序后才能双指针收缩，并按相邻值去重
        List<List<Integer>> answer = new ArrayList<>();

        for (int first = 0; first < nums.length - 2; first++) {
            // 最小的数已大于 0，三者之和不可能为 0
            if (nums[first] > 0) break;

            // 相同的 first 只处理一次
            if (first > 0 && nums[first] == nums[first - 1]) continue;

            int left = first + 1;
            int right = nums.length - 1;

            while (left < right) {
                int sum = nums[first] + nums[left] + nums[right];

                if (sum < 0) {
                    left++; // 和偏小，增大左端
                } else if (sum > 0) {
                    right--; // 和偏大，减小右端
                } else {
                    answer.add(Arrays.asList(nums[first], nums[left], nums[right]));
                    left++;
                    right--;

                    // 跳过刚用过的左右重复值
                    while (left < right && nums[left] == nums[left - 1]) left++;
                    while (left < right && nums[right] == nums[right + 1]) right--;
                }
            }
        }
        return answer;
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class Solution {
    public List<List<Integer>> fourSum(int[] nums, int target) {
        List<List<Integer>> ans = new ArrayList<>();
        Arrays.sort(nums);
        int n = nums.length;
        for (int i = 0; i < n - 3; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) {
                continue;
            }
            // 固定 i 后，最小四数和已经超过 target，后面只会更大
            long min1 = (long) nums[i] + nums[i + 1] + nums[i + 2] + nums[i + 3];
            if (min1 > target) {
                break;
            }
            long max1 = (long) nums[i] + nums[n - 1] + nums[n - 2] + nums[n - 3];
            if (max1 < target) {
                continue;
            }
            for (int j = i + 1; j < n - 2; j++) {
                if (j > i + 1 && nums[j] == nums[j - 1]) {
                    continue;
                }
                long min2 = (long) nums[i] + nums[j] + nums[j + 1] + nums[j + 2];
                if (min2 > target) {
                    break;
                }
                long max2 = (long) nums[i] + nums[j] + nums[n - 1] + nums[n - 2];
                if (max2 < target) {
                    continue;
                }
                int left = j + 1;
                int right = n - 1;
                while (left < right) {
                    // 用 long 避免四个 int 相加溢出
                    long sum = (long) nums[i] + nums[j] + nums[left] + nums[right];
                    if (sum == target) {
                        ans.add(Arrays.asList(nums[i], nums[j], nums[left], nums[right]));
                        left++;
                        right--;
                        while (left < right && nums[left] == nums[left - 1]) {
                            left++;
                        }
                        while (left < right && nums[right] == nums[right + 1]) {
                            right--;
                        }
                    } else if (sum < target) {
                        left++;
                    } else {
                        right--;
                    }
                }
            }
        }
        return ans;
    }
}

import java.util.*;

class Solution {
    public long threeSumCount(int[] nums, int target) {
        Arrays.sort(nums);
        long answer = 0L;

        // i 是三元组第一个下标；不能跳过重复值，不同下标是不同方案。
        for (int i = 0; i < nums.length - 2; i++) {
            int left = i + 1;
            int right = nums.length - 1;

            while (left < right) {
                long sum = (long) nums[i] + nums[left] + nums[right];

                if (sum < target) {
                    left++;
                } else if (sum > target) {
                    right--;
                } else if (nums[left] != nums[right]) {
                    // 两端值不同，一次数完各自连续段，避免逐对重复扫描。
                    int leftValue = nums[left];
                    int rightValue = nums[right];
                    long leftCount = 0;
                    long rightCount = 0;

                    while (left <= right && nums[left] == leftValue) {
                        leftCount++;
                        left++;
                    }
                    while (right >= left && nums[right] == rightValue) {
                        rightCount++;
                        right--;
                    }

                    // 左段任一位置配右段任一位置，都是不同下标方案。
                    answer += leftCount * rightCount;
                } else {
                    // 两端值相同，说明 [left, right] 内全部是同一个数。
                    long count = right - left + 1L;

                    // 从这段里任取两个下标与 i 组成三元组：C(count, 2)。
                    answer += count * (count - 1) / 2;
                    break;
                }
            }
        }

        return answer;
    }
}

import java.util.*;

class Solution {
    public int triangleNumber(int[] nums) {
        Arrays.sort(nums);
        int count = 0;

        // k 固定当前最长边，更长的边已经在右侧处理过。
        for (int k = nums.length - 1; k >= 2; k--) {
            int left = 0;
            int right = k - 1;

            while (left < right) {
                if (nums[left] + nums[right] > nums[k]) {
                    // 最短边已够长，left 到 right-1 都能与 right 配成三角形。
                    count += right - left;
                    right--;
                } else {
                    left++;
                }
            }
        }

        return count;
    }
}

import java.util.*;

class Solution {
    public void moveZeroes(int[] nums) {
        // 下一个非零元素应落在 write
        int write = 0;

        for (int read = 0; read < nums.length; read++) {
            if (nums[read] != 0) {
                // 交换后非零按原顺序前移，write==read 时等于不动
                int temp = nums[write];
                nums[write] = nums[read];
                nums[read] = temp;
                write++;
            }
        }
    }
}

import java.util.*; // 模板导入，排序只在原数组上交换。

class Solution {
    public void sortColors(int[] nums) {
        int zero = 0;              // [0, zero) 全部是 0。
        int current = 0;           // [zero, current) 全部是 1。
        int two = nums.length - 1; // (two, n-1] 全部是 2。

        while (current <= two) {
            if (nums[current] == 0) {
                swap(nums, current, zero);
                zero++;
                current++; // zero 原先小于 current 时换回已处理的 1；原先相等时是自交换，0 已归位。
            } else if (nums[current] == 2) {
                swap(nums, current, two);
                two--;
                // 右边换入的值还没看过，current 停在原地再判断。
            } else {
                current++;
            }
        }
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

public class OddEvenReorder {
    public void reorder(int[] nums) {
        if (nums == null || nums.length <= 1) {
            return;
        }

        int left = 0;
        int right = nums.length - 1;

        while (left < right) {
            // 左侧要放奇数，已经是奇数就继续向右
            while (left < right && (nums[left] & 1) == 1) {
                left++;
            }

            // 右侧要放偶数，已经是偶数就继续向左
            while (left < right && (nums[right] & 1) == 0) {
                right--;
            }

            if (left < right) {
                // 左边的偶数和右边的奇数交换
                int temp = nums[left];
                nums[left] = nums[right];
                nums[right] = temp;
            }
        }
    }
}

class Solution {
    public void reorder(int[] nums) {
        int left = 0;
        int right = nums.length - 1;
        while (left < right) {
            // 最低位为 1 才是奇数，左指针要停在偶数上
            while (left < right && (nums[left] & 1) == 1) {
                left++;
            }
            // 右指针停在奇数上，才能和左边的偶数交换
            while (left < right && (nums[right] & 1) == 0) {
                right--;
            }
            if (left < right) {
                int tmp = nums[left];
                nums[left] = nums[right];
                nums[right] = tmp;
            }
        }
    }
}

import java.util.*;

class Solution {
    public void merge(int[] nums1, int m, int[] nums2, int n) {
        int i = m - 1;       // 从有效段末尾读，避免稍后写入盖掉未处理的 nums1。
        int j = n - 1;       // nums2 尚未放入的最后一个元素。
        int write = m + n - 1; // 空位在尾部，从右往左填才不会踩到未读数据。

        // 较大者先写入 write；相等时走 else，先放 nums2[j]。
        while (i >= 0 && j >= 0) {
            if (nums1[i] > nums2[j]) {
                nums1[write--] = nums1[i--];
            } else {
                nums1[write--] = nums2[j--];
            }
        }

        // nums2 还有剩余时必须继续写入；nums1 剩余前缀已在最终位置。
        while (j >= 0) {
            nums1[write--] = nums2[j--];
        }
        // nums1 若有剩余，它们已经位于正确位置，不需要处理。
    }
}

import java.util.ArrayList;
import java.util.List;

public class IntersectionOfSortedArrays {
    public List<Integer> intersect(int[][] arrays) {
        List<Integer> ans = new ArrayList<>();
        if (arrays == null || arrays.length == 0) {
            return ans;
        }

        int k = arrays.length;
        for (int[] arr : arrays) {
            // 有一个数组为空，交集一定为空
            if (arr == null || arr.length == 0) {
                return ans;
            }
        }

        int[] idx = new int[k];

        while (true) {
            int maxVal = Integer.MIN_VALUE;
            boolean finished = false;

            // 当前最大的候选才可能同时出现在所有数组里
            for (int i = 0; i < k; i++) {
                if (idx[i] == arrays[i].length) {
                    finished = true;
                    break;
                }
                maxVal = Math.max(maxVal, arrays[i][idx[i]]);
            }
            if (finished) {
                break;
            }

            boolean allEqual = true;
            for (int i = 0; i < k; i++) {
                // 比 maxVal 小的值不可能再进交集，指针只向前跳
                while (idx[i] < arrays[i].length && arrays[i][idx[i]] < maxVal) {
                    idx[i]++;
                }
                if (idx[i] == arrays[i].length) {
                    finished = true;
                    break;
                }
                if (arrays[i][idx[i]] != maxVal) {
                    allEqual = false;
                }
            }
            if (finished) {
                break;
            }

            if (allEqual) {
                ans.add(maxVal);
                for (int i = 0; i < k; i++) {
                    int cur = arrays[i][idx[i]];
                    // 同一个值只记录一次，连续重复全部跳过
                    while (idx[i] < arrays[i].length && arrays[i][idx[i]] == cur) {
                        idx[i]++;
                    }
                }
            }
        }

        return ans;
    }
}

import java.util.*; // Java 常用集合、队列、堆与数组工具

class Solution {
    public int findDuplicate(int[] nums) {
        // 长度 n+1、值域 1..n，必有两个位置指向同一值并成环。
        int slow = nums[0];
        int fast = nums[0];

        // 快慢指针在环内相遇。
        do {
            slow = nums[slow];
            fast = nums[nums[fast]];
        } while (slow != fast);

        // 一指针回到起点同速走，相遇点即环入口，也就是重复值。
        int seeker = nums[0];
        while (seeker != slow) {
            seeker = nums[seeker];
            slow = nums[slow];
        }

        return seeker;
    }
}
